class SalesDAO {
  async getMonthlySales(): Promise<SalesRecord[]> {
    const conn = await createConnection();
    try {
      const result = await conn.query("SELECT date, amount FROM sales WHERE date >= $1", [startOfMonth()]);
      return result.rows.map((r) => new SalesRecord(r.date, r.amount));
    } finally {
      await conn.close();
    }
  }
}

